def main():
    dataset = ROOT / 'kg_datasets/dblp/course_v4_holdout_20261007_29'
    jobs = dataset / 'jobs/generation.jsonl'
    assert c.file_sha256(jobs) == 'aaf5edcf9ca24ee87a8efb096668c25226c7c66ccf01a781afe214963c98ff41'
    payloads = c.read_jsonl(jobs)
    assert len(ROWS) == len(payloads) == 200 and [r[0] for r in ROWS] == list(range(200))
    decisions = []
    for i, spans, pairs, entity_reason, relation_reason, note in ROWS:
        def literal(item, group=False):
            return {'text': item[1], 'label': M if group else item[0]} | ({'occurrence': item[2]} if len(item) == 3 else {})
        entities = [literal(item) for item in spans if item[0] != G]
        groups = [literal(item, True) for item in spans if item[0] == G]
        decisions.append({'sampleId': payloads[i]['sampleId'], 'entityStatus': 'unresolved' if entity_reason else 'complete',
            'entityReason': entity_reason, 'entities': entities, 'groupMentions': groups,
            'relationStatus': 'unresolved' if entity_reason or relation_reason else 'complete',
            'relationReason': relation_reason or ('Entity boundaries unresolved.' if entity_reason else ''),
            'relations': [{'head': f'e{h+1}', 'tail': f'e{t+1}', 'label': label, 'reason': reason} for h,t,label,reason in pairs],
            'notes': note})
    output = ROOT / 'kg_datasets/dblp/course_v4_runs/holdout_generation_decisions_20261007_29_fixed.json'
    if output.exists(): raise FileExistsError('Preserve actual AI semantic decisions')
    c.write_json(output, {'provider': 'current_codex_session', 'model': 'unknown_session_model', 'round': 'generation', 'decisions': decisions})
    print(f'Authored {len(decisions)} decisions; this script did not call a model.')


if __name__ == '__main__': main()
